// The lifecycle status of a tenant.
// Ref: #/components/schemas/TenantStatus
type TenantStatus string

const (
	TenantStatusActive    TenantStatus = "active"
	TenantStatusSuspended TenantStatus = "suspended"
	TenantStatusDeleting  TenantStatus = "deleting"
	TenantStatusDeleted   TenantStatus = "deleted"
)

// AllValues returns all TenantStatus values.
func (TenantStatus) AllValues() []TenantStatus {
	return []TenantStatus{
		TenantStatusActive,
		TenantStatusSuspended,
		TenantStatusDeleting,
		TenantStatusDeleted,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s TenantStatus) MarshalText() ([]byte, error) {
	switch s {
	case TenantStatusActive:
		return []byte(s), nil
	case TenantStatusSuspended:
		return []byte(s), nil
	case TenantStatusDeleting:
		return []byte(s), nil
	case TenantStatusDeleted:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *TenantStatus) UnmarshalText(data []byte) error {
	switch TenantStatus(data) {
	case TenantStatusActive:
		*s = TenantStatusActive
		return nil
	case TenantStatusSuspended:
		*s = TenantStatusSuspended
		return nil
	case TenantStatusDeleting:
		*s = TenantStatusDeleting
		return nil
	case TenantStatusDeleted:
		*s = TenantStatusDeleted
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

